// Vérifier si un fichier a été trouvé
const items = $input.all();

if (items.length === 0) {
  return [
    {
      json: {
        success: false,
        message: "Document non trouvé dans Google Drive",
        searchTerm: $('Webhook POST').item.json.body.index,
        dossier: $('Webhook POST').item.json.body.dossier
      }
    }
  ];
}

// Prendre le premier fichier trouvé
const file = items[0].json;

return [
  {
    json: {
      success: true,
      file: {
        id: file.id,
        name: file.name,
        mimeType: file.mimeType,
        webViewLink: file.webViewLink,
        webContentLink: file.webContentLink,
        thumbnailLink: file.thumbnailLink,
        iconLink: file.iconLink,
        size: file.size,
        createdTime: file.createdTime,
        modifiedTime: file.modifiedTime
      },
      searchTerm: $('Webhook POST').item.json.body.index,
      dossier: $('Webhook POST').item.json.body.dossier
    }
  }
];

// ============================================================
// EXTRACT FORM DATA — V4
//
// DOIT être placé directement après le Form Trigger.
// C'est le SEUL nœud où item.binary est accessible.
//
// On lit le fichier via getBinaryDataBuffer et on le stocke
// en base64 dans le JSON afin qu'il soit disponible dans
// tous les nœuds Code en aval via $('Extract Form Data1')
// sans jamais toucher à .binary (inaccessible en task runner).
// ============================================================
const EXT_MIME = {
  pdf:  'application/pdf',
  xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  xls:  'application/vnd.ms-excel',
  docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  doc:  'application/msword'
};

const item = $input.item;

if (!item.binary || Object.keys(item.binary).length === 0) {
  throw new Error('Aucun fichier reçu dans le formulaire. Vérifiez le champ Files.');
}

const binaryKey  = Object.keys(item.binary)[0];
const fileBin    = item.binary[binaryKey];
const ext        = (fileBin.fileExtension || '').toLowerCase();
const mimeType   = EXT_MIME[ext] || 'application/pdf';
const fileExt    = ext ? '.' + ext : '';
const crossRef   = item.json['Cross référence'];
const docName    = item.json['Document'];
const fileName   = '[' + crossRef + ']-' + docName + fileExt;

// Lecture du fichier en buffer et conversion base64
const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
const base64 = buffer.toString('base64');

return [{
  json: {
    Client:            item.json.Client,
    Exercice:          item.json.Exercice,
    'Cycle comptable': item.json['Cycle comptable'],
    'Cross référence': crossRef,
    Document:          docName,
    _fileName:         fileName,
    _fileExt:          ext,
    _fileMimeType:     mimeType,
    _fileBase64:       base64
  }
}];

// ============================================================
// PREPARE UPLOAD (existing) — V4
// Reconstruit le binaire depuis base64 stocké dans
// Extract Form Data. Plus aucune référence à .binary.
// ============================================================
const files = $input.item.json.files;
if (!files || files.length === 0) {
  throw new Error('Dossier cycle introuvable.');
}

const ext      = $('Extract Form Data1').first();
const base64   = ext.json._fileBase64;
const mimeType = ext.json._fileMimeType;
const fileName = ext.json._fileName;

// Reconstruction du binaire avec le bon mimeType
const buffer     = Buffer.from(base64, 'base64');
const binaryData = await this.helpers.prepareBinaryData(buffer, fileName, mimeType);

return [{
  json: {
    targetFolderId: files[0].id,
    fileName:       fileName,
    mimeType:       mimeType
  },
  binary: { data: binaryData }
}];

// ============================================================
// MERGE UPLOAD URL (existing) — V4
// Récupère l'URL d'upload depuis les headers de la réponse
// et rebranche le binaire depuis Prepare Upload (existing)
// ============================================================
const resp      = $input.item.json;
const uploadUrl = resp.headers?.location || resp.headers?.Location;

if (!uploadUrl) {
  throw new Error(
    'Upload URL introuvable. Headers reçus : ' +
    JSON.stringify(resp.headers)
  );
}

const prepareItem = $('Prepare Upload (existing)2').first();

return [{
  json: {
    uploadUrl: uploadUrl,
    fileName:  prepareItem.json.fileName,
    mimeType:  prepareItem.json.mimeType
  },
  binary: { data: prepareItem.binary.data }
}];

// ============================================================
// GENERATE CYCLES LIST — V4 CORRIGÉ
// Ne touche plus à .binary.
// Toutes les données viennent de Extract Form Data (JSON).
// BUG CORRIGÉ : $input.item.json.id au lieu de $[input.item.json.id]
// ============================================================
const cycles = [
  "Capitaux propres", "Charge d'exploitation", "Client",
  "Fournisseur", "Immobilisations", "Impôt et taxes",
  "Personnel", "Stock", "Trésorerie", "Ventes"
];

const clientFolderId = $input.item.json.id;
if (!clientFolderId) throw new Error('ID dossier client manquant.');

const ext         = $('Extract Form Data1').first();
const targetCycle = ext.json['Cycle comptable'];
const fileName    = ext.json._fileName;
const mimeType    = ext.json._fileMimeType;

return cycles.map(cycle => ({
  json: {
    cycleName:   cycle,
    parentId:    clientFolderId,
    targetCycle: targetCycle,
    fileName:    fileName,
    mimeType:    mimeType
  }
}));

// ============================================================
// FILTER + PREPARE UPLOAD (new) — V4 CORRIGÉ
// Reconstruit le binaire depuis base64 stocké dans Extract Form Data.
// BUG CORRIGÉ : item.json.name et matchingFolder.json.id
// sans syntaxe markdown parasite.
// ============================================================
const createdFolders = $input.all();
const cyclesMeta     = $('Generate Cycles List3').all();

if (!cyclesMeta || cyclesMeta.length === 0) {
  throw new Error('Aucune donnée trouvée dans Generate Cycles List2.');
}

const targetCycle = cyclesMeta[0].json.targetCycle;
const fileName    = cyclesMeta[0].json.fileName;
const mimeType    = cyclesMeta[0].json.mimeType;

const matchingFolder = createdFolders.find(item => item.json.name === targetCycle);
if (!matchingFolder) {
  throw new Error(
    `Dossier "${targetCycle}" introuvable. ` +
    `Dossiers créés : ${createdFolders.map(i => i.json.name).join(', ')}`
  );
}

// Reconstruction du binaire depuis Extract Form Data
const ext    = $('Extract Form Data1').first();
const base64 = ext.json._fileBase64;

const buffer     = Buffer.from(base64, 'base64');
const binaryData = await this.helpers.prepareBinaryData(buffer, fileName, mimeType);

return [{
  json: {
    targetFolderId: matchingFolder.json.id,
    fileName:       fileName,
    mimeType:       mimeType
  },
  binary: { data: binaryData }
}];

