    Exercice:          item.json.Exercice.toString().trim(),
    'Cycle comptable': item.json['Cycle comptable'],
    'Cross référence': crossRef,
    Document:          docName,
    _fileName:         fileName,
    _fileExt:          ext,
    _fileMimeType:     mimeType,
    _fileBase64:       base64
  }
}];

// ============================================================
// EXTRACT CAC ID — V5  [NOUVEAU NŒUD ANTI-DOUBLON]
//
// Problème corrigé :
//   Dans Find Client Folder2, l'expression $json.files[0].id
//   pouvait échouer silencieusement si Dossier CAC n'était
//   pas trouvé → Find Client Folder2 retournait files:[] →
//   Client Folder Exists2 basculait sur FALSE → création
//   d'un doublon à chaque exécution.
//
// Ce nœud :
//   1. Valide explicitement que Dossier CAC existe (erreur claire sinon)
//   2. Extrait cacId de façon fiable
//   3. Construit folderName normalisé (déjà en uppercase)
//   4. Expose cacId et folderName comme champs JSON simples
//      → Find Client Folder2 utilise $json.cacId et $json.folderName
//        sans expression imbriquée risquée
// ============================================================

const cacData = $input.item.json;

if (!cacData.files || cacData.files.length === 0) {
  throw new Error(
    'Dossier CAC introuvable dans Google Drive. ' +
    'Créez un dossier nommé exactement "Dossier CAC" à la racine de Mon Drive.'
  );
}

const cacId = cacData.files[0].id;

const ext        = $('Extract Form Data').first().json;
const clientName = ext.Client;    // déjà en MAJUSCULES
const exercice   = ext.Exercice;
const folderName = clientName + '-' + exercice;

return [{
  json: {
    cacId:      cacId,
    folderName: folderName
  }
}];

